  // Sand and ocean on the east edge.
  g.fillStyle = '#e8d29a'; g.fillRect(toPx(CITY.beachX - 6), 0, px(60), S);
  g.fillStyle = '#1e6fa8'; g.fillRect(toPx(CITY.oceanX), 0, S - toPx(CITY.oceanX), S);
  g.fillStyle = 'rgba(255,255,255,0.25)';
